  "investigate": [],
  "hypotheses": [
    {
      "service": "worker",
      "kind": "bad_deploy",
      "mechanism": "Worker v1.1 (deployed t=464) introduced 'acknowledge on receipt' behaviour; the worker crashes health checks repeatedly (2.53/s restarts since t=500), so pending messages are never picked up — they remain in state 'pending' rather than being processed, causing queue depth to reach 729 and 11 orders to go orphaned beyond the 2-minute SLA.",
      "supporting": ["E1", "E5", "E6", "E8", "E9", "E21", "E22"],
      "refuting": [],
      "explains": ["I2_no_orphaned_orders", "E1", "E5", "E6", "E8", "E21", "E22"],
      "repair_plan": [
        {"action": "rollback_service", "params": {"service": "worker"}},
        {"action": "requeue_orphaned_orders", "params": {}}
      ]
    }
  ],
  "summary": "Worker v1.1 (deployed t=464) causes continuous health-check-triggered restarts, leaving 729 messages permanently pending and 11 orders orphaned beyond their 2-minute pickup SLA; rolling back the worker and re-queuing orphaned orders will restore normal processing."
}
